INSERT INTO `wp_posts` VALUES (74,1,'2026-09-02 03:13:45','2026-09-02 03:13:45','<!-- wp:html -->\n<style>\n  :root {\n    --global-color-primary: #ffb703;\n    --global-color-secondary: #00f5d4;\n    --global-color-dark: #12141d;\n    --global-color-card: #1e2230;\n    --global-color-text: #e2e8f0;\n    --global-color-muted: #94a3b8;\n    --global-font-main: \'Inter\', system-ui, -apple-system, sans-serif;\n  }\n\n  .biber-homepage-wrapper {\n    font-family: var(--global-font-main);\n    color: var(--global-color-text);\n    background-color: var(--global-color-dark);\n    padding: 40px 24px;\n    border-radius: 16px;\n    margin: 20px 0;\n    box-shadow: 0 10px 30px rgba(0,0,0,0.4);\n  }\n\n  .elementor-section-hero {\n    padding: 30px 0 50px 0;\n  }\n\n  .elementor-container {\n    max-width: 1200px;\n    margin: 0 auto;\n  }\n\n  .elementor-row {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: center;\n    gap: 40px;\n  }\n\n  .elementor-column-left {\n    flex: 1;\n    min-width: 320px;\n  }\n\n  .elementor-column-right {\n    flex: 1;\n    min-width: 320px;\n    text-align: center;\n  }\n\n  .elementor-widget-heading h1 {\n    font-size: 44px;\n    font-weight: 800;\n    line-height: 1.2;\n    margin-bottom: 20px;\n    color: #ffffff;\n    letter-spacing: -0.5px;\n  }\n\n  .elementor-widget-heading h1 span {\n    color: var(--global-color-primary);\n  }\n\n  .elementor-widget-text-editor p {\n    font-size: 16px;\n    line-height: 1.6;\n    color: var(--global-color-muted);\n    margin-bottom: 32px;\n  }\n\n  .btn-glow {\n    display: inline-block;\n    padding: 16px 36px;\n    background: linear-gradient(135deg, var(--global-color-primary), #f77f00);\n    color: #000000 !important;\n    font-weight: 800;\n    font-size: 16px;\n    text-decoration: none !important;\n    border-radius: 50px;\n    box-shadow: 0 0 20px rgba(255, 183, 3, 0.5);\n    transition: all 0.3s ease;\n    cursor: pointer;\n  }\n\n  .btn-glow:hover {\n    transform: scale(1.05);\n    box-shadow: 0 0 30px rgba(255, 183, 3, 0.9), 0 0 40px rgba(0, 245, 212, 0.6);\n  }\n\n  .elementor-widget-image img {\n    width: 100%;\n    max-width: 460px;\n    border-radius: 20px;\n    box-shadow: 0 15px 35px rgba(0,0,0,0.6);\n    display: block;\n    margin: 0 auto;\n    object-fit: cover;\n  }\n\n  .elementor-section-products {\n    padding: 50px 0 20px 0;\n    border-top: 1px solid rgba(255,255,255,0.08);\n  }\n\n  .elementor-section-products h2 {\n    font-size: 32px;\n    font-weight: 700;\n    text-align: center;\n    margin-bottom: 8px;\n    color: #ffffff;\n  }\n\n  .section-subtitle {\n    text-align: center;\n    color: var(--global-color-muted);\n    margin-bottom: 40px;\n    font-size: 15px;\n  }\n\n  .product-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n    gap: 24px;\n  }\n\n  .product-card {\n    background-color: var(--global-color-card);\n    border-radius: 14px;\n    padding: 20px;\n    border: 1px solid rgba(255,255,255,0.06);\n    transition: transform 0.3s ease, box-shadow 0.3s ease;\n  }\n\n  .product-card:hover {\n    transform: translateY(-6px);\n    box-shadow: 0 12px 24px rgba(0,0,0,0.4);\n  }\n\n  .product-card img {\n    width: 100%;\n    height: 180px;\n    object-fit: cover;\n    border-radius: 10px;\n    margin-bottom: 16px;\n  }\n\n  .product-card h3 {\n    font-size: 17px;\n    font-weight: 700;\n    margin-bottom: 6px;\n    color: #ffffff;\n  }\n\n  .product-card .price {\n    font-size: 18px;\n    font-weight: 800;\n    color: var(--global-color-primary);\n    margin-top: 10px;\n  }\n\n  @media (max-width: 768px) {\n    .elementor-widget-heading h1 {\n      font-size: 28px;\n    }\n    .biber-homepage-wrapper {\n      padding: 24px 16px;\n    }\n    .elementor-row {\n      flex-direction: column;\n    }\n  }\n</style>\n\n<div class=\"biber-homepage-wrapper\">\n  <!-- HERO SECTION (2 COLUMNS) -->\n  <section class=\"elementor-section-hero\">\n    <div class=\"elementor-container\">\n      <div class=\"elementor-row\">\n        \n        <!-- COLUMN 1: Heading H1, Text, Glow CTA Button -->\n        <div class=\"elementor-column-left\">\n          <div class=\"elementor-widget-heading\">\n            <h1>Chinh Phục Mọi Nẻo Đường Với <span>Mũ Bảo Hiểm Biber</span></h1>\n          </div>\n\n          <div class=\"elementor-widget-text-editor\">\n            <p>Bảo vệ tối đa hành trình phượt của bạn với các dòng mũ Fullface, 3/4 và Lật hàm chính hãng AGV, Shoei, HJC đạt chuẩn an toàn quốc tế ECE 22.06 &amp; DOT.</p>\n          </div>\n\n          <div class=\"elementor-widget-button\">\n            <a href=\"#products\" class=\"btn-glow\">\n              ⚡ Khám Phá Sản Phẩm\n            </a>\n          </div>\n        </div>\n\n        <!-- COLUMN 2: WebP Image -->\n        <div class=\"elementor-column-right\">\n          <div class=\"elementor-widget-image\">\n            <img src=\"https://images.unsplash.com/photo-1599819811279-d5ad9cccf838?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" alt=\"Mũ Bảo Hiểm Fullface AGV K1 S Nén WebP\">\n          </div>\n        </div>\n\n      </div>\n    </div>\n  </section>\n\n  <!-- PRODUCTS SECTION -->\n  <section class=\"elementor-section-products\" id=\"products\">\n    <div class=\"elementor-container\">\n      <div class=\"elementor-widget-heading\">\n        <h2>Sản Phẩm Mũ Bảo Hiểm Nổi Bật</h2>\n      </div>\n      <p class=\"section-subtitle\">Đồng bộ từ cấu trúc Data Architecture &amp; WooCommerce</p>\n\n      <div class=\"product-grid\">\n        <div class=\"product-card\">\n          <img src=\"https://images.unsplash.com/photo-1599819811279-d5ad9cccf838?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" alt=\"AGV K1 S\">\n          <h3>Mũ Fullface AGV K1 S Solid Black</h3>\n          <p style=\"font-size: 13px; color: var(--global-color-muted);\">Chuẩn an toàn ECE 22.06</p>\n          <div class=\"price\">3.950.000 ₫</div>\n        </div>\n\n        <div class=\"product-card\">\n          <img src=\"https://images.unsplash.com/photo-1599819811279-d5ad9cccf838?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" alt=\"Shoei X-Fifteen\">\n          <h3>Mũ Fullface Shoei X-Fifteen White</h3>\n          <p style=\"font-size: 13px; color: var(--global-color-muted);\">Chuẩn JIS, SNELL &amp; ECE</p>\n          <div class=\"price\">18.500.000 ₫</div>\n        </div>\n\n        <div class=\"product-card\">\n          <img src=\"https://images.unsplash.com/photo-1575844693280-a420df2e4704?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" alt=\"KYT Venom\">\n          <h3>Mũ 3/4 KYT Venom Thor Marvel</h3>\n          <p style=\"font-size: 13px; color: var(--global-color-muted);\">Chuẩn ECE 22.05</p>\n          <div class=\"price\">2.200.000 ₫</div>\n        </div>\n\n        <div class=\"product-card\">\n          <img src=\"https://images.unsplash.com/photo-1608508060274-1c31754c44d1?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" alt=\"LS2 FF906\">\n          <h3>Mũ Lật Hàm LS2 FF906 Advant Carbon</h3>\n          <p style=\"font-size: 13px; color: var(--global-color-muted);\">Sợi Carbon 180°</p>\n          <div class=\"price\">12.500.000 ₫</div>\n        </div>\n      </div>\n    </div>\n  </section>\n</div>\n<!-- /wp:html -->','Trang chủ','','inherit','closed','closed','','71-revision-v1','','','2026-09-02 03:13:45','2026-09-02 03:13:45','',71,'http://localhost:10004/?p=74',0,'revision','',0);
