INSERT INTO `wp_posts` VALUES (79,1,'2026-09-02 03:56:29','2026-09-02 03:56:29','<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"50px\",\"bottom\":\"50px\",\"left\":\"20px\",\"right\":\"20px\"}},\"color\":{\"background\":\"#0a0c10\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-background\" style=\"background-color:#0a0c10;padding-top:50px;padding-right:20px;padding-bottom:50px;padding-left:20px\"><!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"fontSize\":\"42px\"},\"color\":{\"text\":\"#ffffff\"}}} -->\n<h1 class=\"wp-block-heading has-text-color\" style=\"color:#ffffff;font-size:42px\">Chinh Phục Mọi Nẻo Đường Với <span style=\"color:#ffb703\">Mũ Bảo Hiểm Biber</span></h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"#cbd5e1\"},\"typography\":{\"fontSize\":\"17px\"}}} -->\n<p class=\"has-text-color\" style=\"color:#cbd5e1;font-size:17px\">Bảo vệ tối đa hành trình của bạn với các dòng mũ Fullface, 3/4 và Lật hàm chính hãng AGV, Shoei, HJC đạt chuẩn an toàn quốc tế ECE 22.06 &amp; DOT.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"color\":{\"background\":\"#ffb703\",\"text\":\"#000000\"},\"border\":{\"radius\":\"99px\"}},\"className\":\"btn-glow\"} -->\n<div class=\"wp-block-button btn-glow\"><a class=\"wp-block-button__link has-text-color has-background\" style=\"border-radius:99px;background-color:#ffb703;color:#000000;font-weight:800;padding:14px 32px\" href=\"#danh-sach-mu\">⚡ Khám Phá Sản Phẩm Ngay</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"https://images.unsplash.com/photo-1558981806-ec527fa84c39?w=800\" alt=\"Mũ Bảo Hiểm Fullface AGV K1 S Nén WebP\" style=\"border-radius:16px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"28px\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\" style=\"font-size:28px;margin-top:40px\">Sản Phẩm Mũ Bảo Hiểm Nổi Bật</h2>\n<!-- /wp:heading -->\n\n<!-- wp:woocommerce/product-collection {\"queryId\":1,\"query\":{\"perPage\":9,\"pages\":0,\"offset\":0,\"postType\":\"product\",\"order\":\"asc\",\"orderBy\":\"post__in\",\"search\":\"\",\"exclude\":[],\"inherit\":false,\"taxQuery\":[],\"isProductCollectionBlock\":true,\"featured\":false,\"woocommerceOnSale\":false,\"woocommerceStockStatus\":[\"instock\",\"outofstock\",\"onbackorder\"],\"woocommerceAttributes\":[],\"woocommerceHandPickedProducts\":[\"45\",\"47\",\"55\",\"44\",\"46\",\"54\",\"40\",\"60\",\"42\",\"52\",\"53\",\"43\",\"41\",\"58\",\"59\",\"50\",\"51\",\"49\",\"56\",\"57\",\"48\"],\"filterable\":false,\"relatedBy\":{\"categories\":true,\"tags\":true}},\"tagName\":\"div\",\"displayLayout\":{\"type\":\"flex\",\"columns\":5,\"shrinkColumns\":true},\"dimensions\":{\"widthType\":\"fill\"},\"collection\":\"woocommerce/product-collection/hand-picked\",\"hideControls\":[\"inherit\",\"hand-picked\",\"filterable\",\"order\"],\"queryContextIncludes\":[\"collection\"]} -->\n<div class=\"wp-block-woocommerce-product-collection\"><!-- wp:heading {\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}}} -->\n<h2 class=\"wp-block-heading\" style=\"margin-bottom:1rem\">Recommended products</h2>\n<!-- /wp:heading -->\n\n<!-- wp:woocommerce/product-template -->\n<!-- wp:woocommerce/product-image {\"showSaleBadge\":false,\"isDescendentOfQueryLoop\":true,\"style\":{\"dimensions\":{\"aspectRatio\":\"1/1\"}}} -->\n<!-- wp:woocommerce/product-sale-badge {\"align\":\"right\"} /-->\n<!-- /wp:woocommerce/product-image -->\n\n<!-- wp:post-title {\"isLink\":true,\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"0.75rem\",\"top\":\"0\"}},\"typography\":{\"lineHeight\":\"1.4\"}},\"fontSize\":\"medium\",\"__woocommerceNamespace\":\"woocommerce/product-collection/product-title\"} /-->\n\n<!-- wp:woocommerce/product-price {\"isDescendentOfQueryLoop\":true,\"textAlign\":\"center\",\"fontSize\":\"small\"} /-->\n\n<!-- wp:woocommerce/product-button {\"textAlign\":\"center\",\"isDescendentOfQueryLoop\":true,\"fontSize\":\"small\"} /-->\n<!-- /wp:woocommerce/product-template -->\n\n<!-- wp:query-pagination {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<!-- wp:query-pagination-previous /-->\n\n<!-- wp:query-pagination-numbers /-->\n\n<!-- wp:query-pagination-next /-->\n<!-- /wp:query-pagination --></div>\n<!-- /wp:woocommerce/product-collection -->','Trang chủ','','inherit','closed','closed','','71-revision-v1','','','2026-09-02 03:56:29','2026-09-02 03:56:29','',71,'http://localhost:10004/?p=79',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (80,1,'2026-09-06 09:00:00','2026-09-06 09:00:00','\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost:10004/wp-content/uploads/2026/09/biker-helmet-size-guide.webp\" alt=\"Ảnh hướng dẫn đo kích thước mũ bảo hiểm fullface cho phượt thủ\" style=\"border-radius:12px;width:100%\" /></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Chọn đúng <strong>kích thước mũ bảo hiểm fullface</strong> là yếu tố sống còn quyết định sự an toàn và độ thoải mái cho mỗi phượt thủ trên các cung đường phượt dài. Một chiếc mũ bảo hiểm quá rộng có thể bị lệch khi xảy ra va chạm, trong khi mũ quá chật sẽ gây đau đầu và cản trở lưu thông máu.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Tại Sao Việc Chọn Đúng Kích Thước Mũ Bảo Hiểm Fullface Lại Cực Kỳ Quan Trọng?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Theo tiêu chuẩn an toàn quốc tế mới nhất <a href=\"https://unece.org\" target=\"_blank\" rel=\"noopener\">ECE 22.06 (United Nations Economic Commission for Europe)</a>, mũ bảo hiểm fullface phải ôm khít lấy vùng sọ và hai bên gò má. Độ hấp thụ lực va đập của lớp xốp EPS bên trong mũ chỉ đạt hiệu quả tối đa khi <strong>kích thước mũ bảo hiểm fullface</strong> vừa vặn hoàn hảo với vòng đầu người đội.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Hướng Dẫn 3 Bước Đo Kích Thước Mũ Bảo Hiểm Fullface Tại Nhà</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Bước 1: Dùng Thước Dây Đo Vòng Đầu Qua Trán</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Bạn dùng một chiếc thước dây mềm, quấn quanh đầu cách chân mày khoảng 1.5 cm đến 2 cm (ngay phía trên lỗ tai). Đây là vị trí vòng đầu lớn nhất giúp bạn xác định được chỉ số <strong>kích thước mũ bảo hiểm fullface</strong> chuẩn xác nhất.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Bước 2: Bảng Đối Chiếu Size Mũ Fullface Chuẩn Quốc Tế</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Sau khi có số đo vòng đầu (tính bằng cm), hãy đối chiếu với bảng kích thước mũ bảo hiểm fullface chuẩn sau đây:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul>\n  <li><strong>Size S</strong>: Vòng đầu từ 55 cm – 56 cm.</li>\n  <li><strong>Size M</strong>: Vòng đầu từ 57 cm – 58 cm.</li>\n  <li><strong>Size L</strong>: Vòng đầu từ 59 cm – 60 cm (Kích thước phổ biến nhất tại Việt Nam).</li>\n  <li><strong>Size XL</strong>: Vòng đầu từ 61 cm – 62 cm.</li>\n  <li><strong>Size XXL</strong>: Vòng đầu từ 63 cm – 64 cm.</li>\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Bước 3: Thử Độ Ôm Gò Má Và Khóa Quai An Toàn</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Khi đội thử mũ fullface mới, hai ốp gò má phải ép nhẹ vào má nhưng không làm bạn cắn vào lưỡi. Hãy lắc nhẹ đầu qua lại; nếu mũ không bị xê dịch tự do nghĩa là bạn đã chọn đúng <strong>kích thước mũ bảo hiểm fullface</strong> phù hợp.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Khám Phá Các Mẫu Mũ Fullface Chính Hãng Tại Biber Helmets</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Nếu bạn đang tìm kiếm mẫu mũ bảo hiểm fullface đạt chuẩn ECE 22.06 &amp; DOT chính hãng, hãy tham khảo ngay bộ sưu tập <a href=\"http://localhost:10004/#danh-sach-mu\">Mũ Fullface AGV K1 S và Shoei X-Fifteen</a> tại cửa hàng Biber Helmets với đầy đủ các size từ S đến XXL.</p>\n<!-- /wp:paragraph -->\n','Hướng Dẫn Đo Kích Thước Mũ Bảo Hiểm Fullface Chuẩn ECE 22.06 Cho Phượt Thủ','Hướng dẫn chi tiết cách đo kích thước mũ bảo hiểm fullface chính xác từng milimet cho phượt thủ. Đạt chuẩn an toàn ECE 22.06 &amp; DOT tại Biber Helmets.','publish','open','open','','huong-dan-do-kich-thuoc-mu-bao-hiem-fullface','','','2026-09-02 04:13:23','2026-09-02 04:13:23','',0,'http://localhost:10004/?p=80',0,'post','',0);
INSERT INTO `wp_posts` VALUES (81,1,'2026-09-09 14:30:00','2026-09-09 14:30:00','\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost:10004/wp-content/uploads/2026/09/biker-helmet-top5-review.webp\" alt=\"Top 5 mũ bảo hiểm 3/4 tốt nhất và lật hàm cao cấp 2026\" style=\"border-radius:12px;width:100%\" /></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Dòng <strong>mũ bảo hiểm 3/4 tốt nhất</strong> luôn là sự lựa chọn hàng đầu của phượt thủ nhờ sự kết hợp hoàn hảo giữa độ thông thoáng khi đi phố và khả năng bảo vệ an toàn khi đi xa. Bài viết này sẽ tổng hợp top 5 dòng mũ 3/4 và mũ lật hàm đáng mua nhất năm 2026.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Đánh Giá Chi Tiết Top 5 Mũ Bảo Hiểm 3/4 Tốt Nhất &amp; Lật Hàm 2026</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">1. Mũ 3/4 KYT Venom Thor Marvel – Thiết Kế Đường Phố Nổi Bật</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>KYT Venom đứng đầu danh sách <strong>mũ bảo hiểm 3/4 tốt nhất</strong> nhờ thiết kế tem Marvel bản quyền độc đáo, vỏ nhựa ADT-Advanced nhẹ và hệ thống kính đôi che nắng tiện lợi cho các chuyến đi ban ngày lẫn ban đêm.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">2. Mũ Lật Hàm LS2 FF906 Advant Carbon – Xoay 180 Độ Linh Hoạt</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>LS2 FF906 sở hữu cằm lật 180 độ ra phía sau, giúp bạn linh hoạt chuyển đổi giữa mũ fullface và dòng <strong>mũ bảo hiểm 3/4 tốt nhất</strong> mà không bị vướng gió khi di chuyển tốc độ cao.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">3. Mũ 3/4 Bulldog Heli Carbon Gold – Đẳng Cấp Sợi Carbon Siêu Nhẹ</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Với chất liệu vỏ làm hoàn toàn từ sợi Carbon cao cấp, Bulldog Heli mang lại trọng lượng siêu nhẹ chỉ khoảng 900 gram, giảm tối đa áp lực lên vai và cổ của phượt thủ.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">4. Mũ 3/4 Givi M30.3 Siena – Chuẩn An Toàn Châu Âu</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Đến từ thương hiệu Givi Ý nổi tiếng, dòng mũ 3/4 Givi M30.3 trang bị khe thông gió thể thao và lớp lót kháng khuẩn tháo rời vệ sinh cực kỳ dễ dàng.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">5. Mũ 3/4 Andes 3S111 – Lựa Chọn Quốc Dân Bền Bỉ</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Andes 3S111 là câu trả lời cho tiêu chuẩn <strong>mũ bảo hiểm 3/4 tốt nhất</strong> trong phân khúc giá rẻ nhờ vỏ nhựa ABS nguyên sinh chịu lực tốt và sơn phủ chống trầy xước cao cấp.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Tiêu Chí Chọn Mũ Bảo Hiểm 3/4 Tốt Nhất Cho Chuyến Đi Phượt Xa</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Khi chọn mua, hãy luôn chú ý kiểm tra chứng nhận kiểm định an toàn quốc tế như <a href=\"https://www.nhtsa.gov\" target=\"_blank\" rel=\"noopener\">DOT (Department of Transportation)</a> hoặc ECE 22.05/22.06. Khám phá ngay các mẫu <a href=\"http://localhost:10004/#danh-sach-mu\">Mũ Bảo Hiểm 3/4 Biber Helmets Chính Hãng</a> với ưu đãi bảo hành 24 tháng.</p>\n<!-- /wp:paragraph -->\n','Top 5 Mũ Bảo Hiểm 3/4 Và Lật Hàm Tốt Nhất Năm 2026 Cho Dân Phượt','Khám phá ngay top 5 mẫu mũ bảo hiểm 3/4 tốt nhất và mũ lật hàm carbon 180 độ năm 2026. Thiết kế hiện đại, chống ồn hiệu quả cho các chuyến đi phượt.','publish','open','open','','top-5-mu-bao-hiem-3-4-va-lat-ham-tot-nhat','','','2026-09-02 04:13:23','2026-09-02 04:13:23','',0,'http://localhost:10004/?p=81',0,'post','',0);
INSERT INTO `wp_posts` VALUES (82,0,'2026-09-02 04:13:23','2026-09-02 04:13:23','\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost:10004/wp-content/uploads/2026/09/biker-helmet-size-guide.webp\" alt=\"Ảnh hướng dẫn đo kích thước mũ bảo hiểm fullface cho phượt thủ\" style=\"border-radius:12px;width:100%\" /></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Chọn đúng <strong>kích thước mũ bảo hiểm fullface</strong> là yếu tố sống còn quyết định sự an toàn và độ thoải mái cho mỗi phượt thủ trên các cung đường phượt dài. Một chiếc mũ bảo hiểm quá rộng có thể bị lệch khi xảy ra va chạm, trong khi mũ quá chật sẽ gây đau đầu và cản trở lưu thông máu.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Tại Sao Việc Chọn Đúng Kích Thước Mũ Bảo Hiểm Fullface Lại Cực Kỳ Quan Trọng?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Theo tiêu chuẩn an toàn quốc tế mới nhất <a href=\"https://unece.org\" target=\"_blank\" rel=\"noopener\">ECE 22.06 (United Nations Economic Commission for Europe)</a>, mũ bảo hiểm fullface phải ôm khít lấy vùng sọ và hai bên gò má. Độ hấp thụ lực va đập của lớp xốp EPS bên trong mũ chỉ đạt hiệu quả tối đa khi <strong>kích thước mũ bảo hiểm fullface</strong> vừa vặn hoàn hảo với vòng đầu người đội.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Hướng Dẫn 3 Bước Đo Kích Thước Mũ Bảo Hiểm Fullface Tại Nhà</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Bước 1: Dùng Thước Dây Đo Vòng Đầu Qua Trán</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Bạn dùng một chiếc thước dây mềm, quấn quanh đầu cách chân mày khoảng 1.5 cm đến 2 cm (ngay phía trên lỗ tai). Đây là vị trí vòng đầu lớn nhất giúp bạn xác định được chỉ số <strong>kích thước mũ bảo hiểm fullface</strong> chuẩn xác nhất.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Bước 2: Bảng Đối Chiếu Size Mũ Fullface Chuẩn Quốc Tế</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Sau khi có số đo vòng đầu (tính bằng cm), hãy đối chiếu với bảng kích thước mũ bảo hiểm fullface chuẩn sau đây:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul>\n  <li><strong>Size S</strong>: Vòng đầu từ 55 cm – 56 cm.</li>\n  <li><strong>Size M</strong>: Vòng đầu từ 57 cm – 58 cm.</li>\n  <li><strong>Size L</strong>: Vòng đầu từ 59 cm – 60 cm (Kích thước phổ biến nhất tại Việt Nam).</li>\n  <li><strong>Size XL</strong>: Vòng đầu từ 61 cm – 62 cm.</li>\n  <li><strong>Size XXL</strong>: Vòng đầu từ 63 cm – 64 cm.</li>\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Bước 3: Thử Độ Ôm Gò Má Và Khóa Quai An Toàn</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Khi đội thử mũ fullface mới, hai ốp gò má phải ép nhẹ vào má nhưng không làm bạn cắn vào lưỡi. Hãy lắc nhẹ đầu qua lại; nếu mũ không bị xê dịch tự do nghĩa là bạn đã chọn đúng <strong>kích thước mũ bảo hiểm fullface</strong> phù hợp.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Khám Phá Các Mẫu Mũ Fullface Chính Hãng Tại Biber Helmets</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Nếu bạn đang tìm kiếm mẫu mũ bảo hiểm fullface đạt chuẩn ECE 22.06 &amp; DOT chính hãng, hãy tham khảo ngay bộ sưu tập <a href=\"http://localhost:10004/#danh-sach-mu\">Mũ Fullface AGV K1 S và Shoei X-Fifteen</a> tại cửa hàng Biber Helmets với đầy đủ các size từ S đến XXL.</p>\n<!-- /wp:paragraph -->\n','Hướng Dẫn Đo Kích Thước Mũ Bảo Hiểm Fullface Chuẩn ECE 22.06 Cho Phượt Thủ','Hướng dẫn chi tiết cách đo kích thước mũ bảo hiểm fullface chính xác từng milimet cho phượt thủ. Đạt chuẩn an toàn ECE 22.06 &amp; DOT tại Biber Helmets.','inherit','closed','closed','','80-revision-v1','','','2026-09-02 04:13:23','2026-09-02 04:13:23','',80,'http://localhost:10004/?p=82',0,'revision','',0);
